package dev.jobflow.service;
import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.databind.node.ObjectNode; import dev.jobflow.domain.JobType; import java.time.Instant; import org.springframework.stereotype.Component;
@Component public class DemoJobExecutors implements JobExecutor {private final ObjectMapper json;public DemoJobExecutors(ObjectMapper j){json=j;} public boolean supports(JobType t){return true;} public JsonNode execute(JsonNode payload)throws JobExecutionException{String failure=payload.path("simulateFailure").asText();if("transient".equals(failure))throw new JobExecutionException("TRANSIENT_SIMULATION","Simulated transient failure",true);if("permanent".equals(failure))throw new JobExecutionException("PERMANENT_SIMULATION","Simulated permanent failure",false);ObjectNode result=json.createObjectNode();result.put("processedAt",Instant.now().toString());result.put("summary","Processed safely by "+payload.path("name").asText("JobFlow"));return result;}}
